using System;using System.IO;using System.Reflection;using DG.Tweening;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.UI;using TMPro;
public static class CompletionPurchaseQA {
static BindingFlags f=BindingFlags.Instance|BindingFlags.NonPublic;static int checks;
static void Set(object o,string n,object v)=>o.GetType().GetField(n,f).SetValue(o,v);
static object Get(object o,string n)=>o.GetType().GetField(n,f).GetValue(o);
static void Check(bool yes,string why){if(!yes)throw new Exception(why);checks++;}
static GameObject Node(string name,Transform parent=null){var go=new GameObject(name,typeof(RectTransform));if(parent!=null)go.transform.SetParent(parent,false);return go;}
static Image Img(string name,Transform p)=>Node(name,p).AddComponent<Image>();
static TMP_Text Label(string name,Transform p)=>Node(name,p).AddComponent<TextMeshProUGUI>();
public static void Start(){EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);EditorSettings.enterPlayModeOptionsEnabled=true;EditorSettings.enterPlayModeOptions=EnterPlayModeOptions.DisableDomainReload;EditorApplication.playModeStateChanged+=Changed;EditorApplication.isPlaying=true;}
static void Changed(PlayModeStateChange state){if(state!=PlayModeStateChange.EnteredPlayMode)return;EditorApplication.playModeStateChanged-=Changed;try{Run();File.WriteAllText(@"E:/SSD/GITHUB/MEQUI BREAK/tmp/customization-purchase-preview/completion-tests.txt","PASS "+checks+" Play Mode checks");EditorApplication.Exit(0);}catch(Exception e){File.WriteAllText(@"E:/SSD/GITHUB/MEQUI BREAK/tmp/customization-purchase-preview/completion-tests.txt",e.ToString());Debug.LogException(e);EditorApplication.Exit(1);}}
static ResultPopup Popup(string name,bool initializeAtLoad){var root=Node(name);root.SetActive(false);var popup=root.AddComponent<ResultPopup>();var overlay=Img("Overlay",root.transform);var panel=Node("Panel",root.transform);panel.GetComponent<RectTransform>().anchoredPosition=new Vector2(0,120);var group=panel.AddComponent<CanvasGroup>();var button=Node("Continue",panel.transform).AddComponent<Button>();Set(popup,"popupPanel",panel.GetComponent<RectTransform>());Set(popup,"popupCanvasGroup",group);Set(popup,"overlayImage",overlay);Set(popup,"titleLabel",Label("Title",panel.transform));Set(popup,"pointsLabel",Label("Points",panel.transform));Set(popup,"ordersSummaryLabel",Label("Summary",panel.transform));Set(popup,"continueButton",button);if(initializeAtLoad){root.SetActive(true);Check(!root.activeSelf,"Active-at-load popup hides initially");}return popup;}
static void Finish(ResultPopup popup){((Sequence)Get(popup,"_activeSequence")).Complete(true);((Sequence)Get(popup,"_pointsSequence")).Complete(true);Check(popup.gameObject.activeInHierarchy,"Result stays active after first Awake");Check(((CanvasGroup)Get(popup,"popupCanvasGroup")).alpha>.99f,"Panel fades in");Check(((Button)Get(popup,"continueButton")).interactable,"Continue becomes interactive");Check(Vector2.Distance(((RectTransform)Get(popup,"popupPanel")).anchoredPosition,new Vector2(0,120))<.01f,"Panel reaches visible position");}
static void Run(){DOTween.Init();var settings=ScriptableObject.CreateInstance<TMP_Settings>();typeof(TMP_Settings).GetField("s_Instance",BindingFlags.Static|BindingFlags.NonPublic).SetValue(null,settings);TMP_Settings.defaultStyleSheet=ScriptableObject.CreateInstance<TMP_StyleSheet>();
var energy=Popup("Energy",false);energy.Show(20);Finish(energy);Check(((TMP_Text)Get(energy,"pointsLabel")).text.Contains("20"),"Reward count reaches 20");energy.gameObject.SetActive(false);energy.Show(0);Finish(energy);Check(((TMP_Text)Get(energy,"pointsLabel")).text.Contains("+0"),"Zero reward still opens result");
foreach(string name in new[]{"RushBalance","ComboCrew"}){var popup=Popup(name,true);popup.Show(8,2,1);Finish(popup);Check(((TMP_Text)Get(popup,"ordersSummaryLabel")).gameObject.activeSelf,"Order summary visible for "+name);Check(((TMP_Text)Get(popup,"ordersSummaryLabel")).text.Contains("2"),"Order summary populated for "+name);}
var energyEnd=Popup("EnergyEndToEnd",false);var eg=Node("EnergyController");eg.SetActive(false);var ec=eg.AddComponent<EnergyStationController>();Set(ec,"resultPopup",energyEnd);Set(ec,"interactionCount",2);Set(ec,"interactionsToComplete",2);Set(ec,"questionSets",null);var stateField=typeof(EnergyStationController).GetField("sessionState",f);stateField.SetValue(ec,Enum.Parse(stateField.FieldType,"ReadyToComplete"));typeof(EnergyStationController).GetMethod("CompleteSession",f).Invoke(ec,null);Finish(energyEnd);Check((bool)Get(ec,"rewardGranted"),"Energy completion is settled once");
var purchaseRoot=Node("PurchaseController");purchaseRoot.SetActive(false);var controller=purchaseRoot.AddComponent<CustomizationController>();var price=Label("Price",purchaseRoot.transform);var slot=Img("SlotGrid",purchaseRoot.transform);var item=Img("PurchaseItem",slot.transform);var outline=item.gameObject.AddComponent<AvatarSpriteOutline>();Set(controller,"purchaseConfirmPrice",price);Set(controller,"purchaseConfirmSlot",slot);Set(controller,"purchaseConfirmItem",item);var tex=new Texture2D(8,8);var sprite=Sprite.Create(tex,new Rect(0,0,8,8),Vector2.one*.5f);foreach(var category in new[]{AvatarCustomizationCategory.Hat,AvatarCustomizationCategory.Face,AvatarCustomizationCategory.Color}){var option=Node(category.ToString(),purchaseRoot.transform);var optionSlot=option.AddComponent<Image>();optionSlot.sprite=sprite;optionSlot.color=Color.gray;option.AddComponent<AvatarOptionButton>();string suffix=category==AvatarCustomizationCategory.Hat?"Hat":category==AvatarCustomizationCategory.Face?"Face":"Color";var source=Img("Preview_"+suffix+"_01",option.transform);source.sprite=sprite;source.color=category==AvatarCustomizationCategory.Face?Color.black:category==AvatarCustomizationCategory.Color?Color.cyan:Color.white;Set(controller,category==AvatarCustomizationCategory.Hat?"hatOptions":category==AvatarCustomizationCategory.Face?"faceOptions":"colorOptions",new[]{option});typeof(CustomizationController).GetMethod("RefreshPurchasePreview",f).Invoke(controller,new object[]{new AvatarCustomizationItem{Category=category,OptionIndex=0,BreakPointCost=125}});Check(price.text=="125 PB","Price only for "+category);Check(item.sprite==source.sprite&&item.color==source.color,"Correct item artwork and tint for "+category);Check(slot.sprite==optionSlot.sprite&&slot.color==optionSlot.color,"Same slot as grid for "+category);Check(outline.enabled==(category!=AvatarCustomizationCategory.Face),"Appropriate item outline for "+category);}
}
}